                  ?? states.Keys.FirstOrDefault();
            if (targetId is null || !states.TryGetValue(targetId, out var care)) return;
            _recordTokens(targetId, care, tokens);
        }
        catch (JsonStoreException ex)
        {
            PersistenceErrorPresenter.Report(ex);
        }
    }

